#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "trisolv.h"

/* Include the Exo-generated kernel header. */
#include "generated/trisolv/trisolv.h"


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		DATA_TYPE POLYBENCH_1D(x,N,n),
		DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      x[i] = - 999;
      b[i] =  i ;
      for (j = 0; j <= i; j++)
	L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Tile size for the inner j-loop. This provides a small constant-trip-count
# loop body that is amenable to full unrolling and keeps a chunk of each
# row L[i, :] and prefix of x[:] hot in cache.
J_TILE = 8

@proc
def kernel_trisolv_base(
    n: size,
    L: DATA_TYPE[n, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    b: DATA_TYPE[n] @ DRAM,
):
    # Forward substitution solve for the lower-triangular system L x = b.
    #
    # For each row i we compute
    #   x[i] = (b[i] - sum_{j=0..i-1} L[i, j] * x[j]) / L[i, i]
    #
    # We introduce a scalar accumulator s so that the inner loop becomes
    # a pure reduction, avoiding repeated loads/stores of x[i].
    for i in seq(0, n):
        # Accumulator lives in a register for this row.
        s: DATA_TYPE
        s = b[i]

        # Triangular inner product with already-computed part of x.
        for j in seq(0, i):
            s = s - L[i, j] * x[j]

        # One division per row by the diagonal element.
        s = s / L[i, i]
        x[i] = s

# Start from the simple, clear base kernel and apply a performance-oriented
# schedule. The final object bound to the name `kernel_trisolv` is what
# will be code-generated and called from C.
kernel_trisolv = kernel_trisolv_base

# 1) Tile the inner j-loop.
#
#    This transforms:
#        for j in seq(0, i):
#            ...
#    into a pair of nested loops over (j_outer, j_inner) with
#    j = J_TILE * j_outer + j_inner, plus guards for the partial tile
#    at the end when i is not a multiple of J_TILE. The order of the
#    valid j-iterations (0..i-1) is preserved, so the floating-point
#    reduction order is unchanged.
kernel_trisolv = divide_loop(
    kernel_trisolv,
    "j",                  # loop to divide
    J_TILE,               # tile size
    ("j_outer", "j_inner"),
    tail="guard",         # handle the last partial tile with guards
)

# 2) Fully unroll the small inner-tile loop.
#
#    After tiling, j_inner has a constant, small upper bound (J_TILE),
#    making it profitable to fully unroll:
#        for j_inner in seq(0, J_TILE):
#            ...
#
#    This removes loop-control overhead and exposes instruction-level
#    parallelism in the hot reduction kernel.
kernel_trisolv = unroll_loop(kernel_trisolv, "j_inner")

# 3) Simplify the resulting IR (e.g., clean up guards and arithmetic).
kernel_trisolv = simplify(kernel_trisolv)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(L, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten views to raw pointers. */
  kernel_trisolv (/*ctxt=*/NULL,
                  n,
                  (DATA_TYPE*)POLYBENCH_ARRAY(L),
                  (DATA_TYPE*)POLYBENCH_ARRAY(x),
                  (DATA_TYPE*)POLYBENCH_ARRAY(b));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(L);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(b);

  return 0;
}
